<script setup>
import { ref,onMounted,onBeforeUnmount,watch } from 'vue'
import { api } from '../api'
import { accountEpoch,storageKey } from '../session'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
const props=defineProps({event:Object,readOnly:Boolean}),emit=defineEmits(['confirmed'])
const bundles=ref([]),job=ref(null),error=ref(''),notice=ref(''),writes=useWorkflowWrite('facts:'+props.event.id),epoch=accountEpoch
const notes=ref([]),supplement=ref(''),draftKey=storageKey('fact-note:'+props.event.id)
try{supplement.value=localStorage.getItem(draftKey)||''}catch{}
watch(supplement,v=>{try{localStorage.setItem(draftKey,v)}catch{}})
async function saveNote(){const text=supplement.value;await act('/events/'+props.event.id+'/fact-notes',{content:text,expected_version:props.event.content_version,bundle_id:bundles.value[0]?.id||null});if(!error.value){supplement.value='';notice.value='补充已单独保存。点击分析会纳入本事件的原文和授权回答，旧账不重发。'}}
let alive=true,timer=null,serial=0
async function load(){const token=++serial;try{const [groups,jobs,savedNotes]=await Promise.all([api.flow('/events/'+props.event.id+'/fact-bundles'),api.flow('/events/'+props.event.id+'/analysis-jobs'),api.flow('/events/'+props.event.id+'/fact-notes')]);if(!alive||epoch!==accountEpoch||token!==serial)return;bundles.value=groups.items;notes.value=savedNotes.items;job.value=jobs.items.find(j=>j.operation==='facts')||null;clearTimeout(timer);if(!props.readOnly&&!document.hidden&&['queued','running'].includes(job.value?.state))timer=setTimeout(load,2000)}catch(e){if(alive)error.value=e.message}}
async function act(path,body={}){if(writes.busy.value)return;error.value='';notice.value='';try{const result=await writes.send(path,body);await load();if(path.endsWith('/confirm')){notice.value='已确认本组事实，新增 '+result.coins_gained+' 币。';emit('confirmed')}}catch(e){error.value=e.message}}
function decision(group,item,value,mainline=item.mainline,related_fact_id=null){return act('/fact-bundles/'+group.id+'/decision',{expected_version:group.version,fragment_id:item.fragment_id,decision:value,mainline,related_fact_id})}
function visibility(){clearTimeout(timer);if(!document.hidden)load()}
watch(()=>props.event.content_version,load)
onMounted(()=>{load();document.addEventListener('visibilitychange',visibility)})
onBeforeUnmount(()=>{alive=false;serial++;clearTimeout(timer);document.removeEventListener('visibilitychange',visibility)})
</script>
<template><section v-if="!readOnly||bundles.length||notes.length" class="card"><h2>{{ readOnly?'历史事实建议（只读）':'逐事实分析与确认' }}</h2><p class="muted">AI 提出事实、属性及档位，程序按规则计算金币；你核对后才入账。同一行动只结算一次。</p><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><template v-if="!readOnly"><button v-if="writes.pending.value" class="btn" :disabled="writes.busy.value" @click="act(writes.pending.value.path,writes.pending.value.body)">恢复上次请求</button><p v-if="job">{{ {queued:'排队中',running:'分析中',ready:'建议已保存',failed:'分析失败',superseded:'来源已变化',cancelled:'已取消'}[job.state] }} {{ job.safe_error_code }}</p><button class="btn" :disabled="writes.busy.value||!!writes.pending.value||['queued','running'].includes(job?.state)" @click="act('/events/'+event.id+'/analysis-jobs',{event_version:event.content_version,operation:'facts'})">{{ bundles.length?'重新分析当前文字':'分析这篇记录' }}</button><button v-if="['queued','running'].includes(job?.state)" class="btn" @click="api.cancelJob(job.id).then(load).catch(e=>error=e.message)">取消分析</button>
<form @submit.prevent="saveNote"><p v-for="question in bundles[0]?.payload.questions||[]" :key="question">{{ question }}</p><label>与这篇事实有关的补充或回答（可不填）<textarea v-model="supplement" maxlength="10000"/></label><p class="muted">另存为本篇的授权补充；不改原文，不自动结算。不需要补充时可直接核对已有建议。</p><button class="btn" :disabled="writes.busy.value||!!writes.pending.value||!supplement.trim()">保存相关补充</button></form></template><details v-if="notes.length"><summary>已保存的相关补充</summary><p v-for="note in notes" :key="note.id">{{ note.content }}</p></details><template v-for="group in bundles.slice(0,1)" :key="group.id"><p>原文 v{{ group.event_version }} · 建议 v{{ group.version }} · {{ group.state==='confirmed'?'已确认':'待核对' }}</p><p class="muted">本次模型 {{ group.provenance.provider }} / {{ group.provenance.model }} · 配置 v{{ group.provenance.config_version }}</p><article v-for="item in group.payload.items" :key="item.fragment_id"><blockquote>{{ item.excerpt }}</blockquote><p class="muted">来源：{{ {original:'原文',note:'相关补充',review_answer:'辅助回顾回答'}[item.source_kind]||'原文' }}</p><p>{{ item.summary }} · {{ {none:'暂不建议行动币',small:'小步有效行动',medium:'持续投入 / 小成果',large:'较大成果 / 阶段推进'}[item.grade] }}</p><p>{{ item.reason }}</p><ul><li v-for="change in (group.preview?group.preview.items.find(i=>i.fragment_id===item.fragment_id)?.changes||[]:item.changes)" :key="change.name">{{ change.name }} {{ change.delta }} · {{ change.reason }}</li></ul><p v-if="item.candidate_fact_id">AI 建议关联已有事实，需核对是否同一次。</p><div v-if="!readOnly&&group.state!=='confirmed'" class="action-group"><button v-for="option in item.candidate_options||[]" :key="option.fact_id" class="btn" :disabled="writes.busy.value||!!writes.pending.value" @click="decision(group,item,'same',item.mainline,option.fact_id)">与已结算事实相同：{{ option.excerpt }}</button><button v-if="item.candidate_fact_id" class="btn" :disabled="writes.busy.value||!!writes.pending.value" @click="decision(group,item,'same')">是同一次行动</button><button v-if="item.candidate_fact_id||item.decision==='unresolved'" class="btn" :disabled="writes.busy.value||!!writes.pending.value" @click="decision(group,item,'distinct')">是另一件事</button><button class="btn" :disabled="writes.busy.value||!!writes.pending.value" @click="decision(group,item,'skip')">本项暂不结算</button><button v-if="item.goal_id" class="btn" :disabled="writes.busy.value||!!writes.pending.value" @click="decision(group,item,'keep',!item.mainline)">{{ item.mainline?'取消主线关联':'确认与当前主线有关' }}</button></div><p v-if="group.preview">{{ group.preview.items.find(i=>i.fragment_id===item.fragment_id)?.booked?'同一行动已入账，本次新增 0':group.preview.items.find(i=>i.fragment_id===item.fragment_id)?.unresolved?'关系待核对':'本次建议 '+(group.preview.items.find(i=>i.fragment_id===item.fragment_id)?.breakdown.amount||0)+' 币' }}</p><p v-if="group.preview?.items.find(i=>i.fragment_id===item.fragment_id)?.booked">本次新增属性 0，旧结算保留。</p><p v-if="group.preview" class="muted">金币拆分：基础 {{ group.preview.items.find(i=>i.fragment_id===item.fragment_id)?.breakdown.base||0 }} · 主线 {{ group.preview.items.find(i=>i.fragment_id===item.fragment_id)?.breakdown.mainline||0 }} · 节日 {{ group.preview.items.find(i=>i.fragment_id===item.fragment_id)?.breakdown.holiday||0 }} · 封顶减 {{ group.preview.items.find(i=>i.fragment_id===item.fragment_id)?.breakdown.cap_reduction||0 }}</p></article><template v-if="!readOnly&&group.state!=='confirmed'"><button class="btn" :disabled="writes.busy.value||!!writes.pending.value" @click="act('/fact-bundles/'+group.id+'/preview',{expected_version:group.version})">刷新整组入账预览</button><div v-if="group.preview"><p>基础、主线及节日合计 {{ group.preview.total }} 币 · 今日此前已用 {{ group.preview.used }}/100</p><button class="btn primary" :disabled="writes.busy.value||!!writes.pending.value||group.preview.items.some(i=>i.unresolved)" @click="act('/fact-bundles/'+group.id+'/confirm',{expected_version:group.version})">确认本组新增事实</button></div></template></template><details v-if="bundles.length>1"><summary>历史分析（只读）</summary><article v-for="group in bundles.slice(1)" :key="group.id"><p>原文 v{{ group.event_version }} · {{ group.state }}</p><p v-for="item in group.payload.items" :key="item.fragment_id">{{ item.excerpt }} · {{ item.summary }}</p></article></details></section></template>
